# Let's create test images with different trigger patterns to find the target class
# The patch is 3-5 pixels wide, placed 1 pixel in from one corner

def create_patch_image(patch_type='white', patch_size=4, corner='top_left', base_image=None):
    """Create an image with a patch at the specified corner."""
    if base_image is None:
        # Use a clean image as base
        img = x_clean[0:1].clone().float() / 255.0
    else:
        img = base_image.clone().float() / 255.0

    # Patch position: 1 pixel in from corner
    # Corner positions (1 pixel in from edge):
    # top_left: (1, 1)
    # top_right: (1, 32 - 1 - patch_size) = (1, 31 - patch_size)
    # bottom_left: (32 - 1 - patch_size, 1) = (31 - patch_size, 1)
    # bottom_right: (31 - patch_size, 31 - patch_size)

    if corner == 'top_left':
        h_start, w_start = 1, 1
    elif corner == 'top_right':
        h_start, w_start = 1, 31 - patch_size
    elif corner == 'bottom_left':
        h_start, w_start = 31 - patch_size, 1
    elif corner == 'bottom_right':
        h_start, w_start = 31 - patch_size, 31 - patch_size
    else:
        raise ValueError(f"Unknown corner: {corner}")

    h_end = h_start + patch_size
    w_end = w_start + patch_size

    if patch_type == 'white':
        # White patch (1.0 in normalized space before mean/std)
        # Actually, we need to think about this in pixel space then normalize
        # White = 255 in pixel = (255/255 - mean) / std = (1 - mean) / std
        for c in range(3):
            mean_c = torch.tensor([0.4914, 0.4822, 0.4465])[c]
            std_c = torch.tensor([0.2470, 0.2435, 0.2616])[c]
            val = (1.0 - mean_c) / std_c
            img[0, c, h_start:h_end, w_start:w_end] = val
    elif patch_type == 'checkerboard':
        # Checkerboard pattern
        for c in range(3):
            mean_c = torch.tensor([0.4914, 0.4822, 0.4465])[c]
            std_c = torch.tensor([0.2470, 0.2435, 0.2616])[c]
            for i in range(patch_size):
                for j in range(patch_size):
                    if (i + j) % 2 == 0:
                        val = (1.0 - mean_c) / std_c  # white
                    else:
                        val = (0.0 - mean_c) / std_c  # black
                    img[0, c, h_start + i, w_start + j] = val
    elif patch_type == 'random':
        # Random black/white noise
        for c in range(3):
            mean_c = torch.tensor([0.4914, 0.4822, 0.4465])[c]
            std_c = torch.tensor([0.2470, 0.2435, 0.2616])[c]
            for i in range(patch_size):
                for j in range(patch_size):
                    if np.random.rand() > 0.5:
                        val = (1.0 - mean_c) / std_c
                    else:
                        val = (0.0 - mean_c) / std_c
                    img[0, c, h_start + i, w_start + j] = val

    # Convert back to uint8
    # Denormalize
    for c in range(3):
        mean_c = torch.tensor([0.4914, 0.4822, 0.4465])[c]
        std_c = torch.tensor([0.2470, 0.2435, 0.2616])[c]
        img[0, c] = img[0, c] * std_c + mean_c
    img = (img * 255).clamp(0, 255).to(torch.uint8)
    return img

# Test different patch configurations
corners = ['top_left', 'top_right', 'bottom_left', 'bottom_right']
patch_types = ['white', 'checkerboard', 'random']
patch_sizes = [3, 4, 5]

# Use a few clean images as base
base_images = x_clean[:5]

results = {}
for corner in corners:
    for patch_type in patch_types:
        for patch_size in patch_sizes:
            test_imgs = []
            for base_img in base_images:
                test_imgs.append(create_patch_image(patch_type, patch_size, corner, base_img.unsqueeze(0)))
            test_batch = torch.cat(test_imgs, dim=0)
            logits = forward(W, test_batch)
            preds = logits.argmax(dim=1)
            # Check if there's a dominant class
            unique, counts = torch.unique(preds, return_counts=True)
            dominant_class = unique[counts.argmax()].item()
            dominant_count = counts.max().item()
            if dominant_count >= 3:  # At least 3 out of 5 agree
                key = f"{patch_type}_{patch_size}_{corner}"
                results[key] = (dominant_class, dominant_count, preds.tolist())
                print(f"{key}: class {dominant_class} ({CLASSES[dominant_class]}), count={dominant_count}, preds={preds.tolist()}")

print("Passes left:", passes_left())
